import gzip,json
from run_sqrt2_power_pilot import ROOT
p=ROOT/'research/arithmetic-library/sqrt2-power/observations/shared-wave-half-log-square-v1/generation-process.json.gz'
with gzip.open(p,'rb') as stream:raw=stream.read(8*1024**2+1)
assert len(raw)<=8*1024**2
rows=json.loads(json.loads(json.loads(raw)['stdout'])['bundle'])[3]
childpos={'imp_intro':[(1,1)],'imp_elim':[(1,0),(2,0)],'cut':[(3,0),(4,1)],'and_intro':[(1,0),(2,0)],'and_elim_l':[(1,0)],'and_elim_r':[(1,0)],'or_intro_l':[(1,0)],'or_intro_r':[(1,0)],'or_elim':[(1,0),(2,1),(3,1)],'bot_elim':[(1,0)],'forall_intro':[(1,0)],'forall_elim':[(1,0)],'exists_intro':[(2,0)],'exists_elim':[(1,0),(2,1)],'eq_sym':[(1,0)],'eq_trans':[(1,0),(2,0)],'cong_s':[(1,0)],'cong_add':[(1,0),(2,0)],'cong_mul':[(1,0),(2,0)],'eq_subst':[(2,0),(3,0)],'ind':[(2,0),(3,0)],'axiom':[],'eq_refl':[],'dne':[]}
unused=[]
for i,r in enumerate(rows):
    k=len(r[2]);body=r[3]
    for _ in range(k):assert body[0]=='imp_intro';body=body[1]
    used=set();pending=[(body,0)]
    while pending:
        b,depth=pending.pop()
        if b[0]=='hyp':
            if b[1]>=depth:assert b[1]-depth<k;used.add(k-1-(b[1]-depth))
        else:
            pending.extend((b[j],depth+inc) for j,inc in childpos[b[0]])
    if len(used)<k:unused.append([i,k,len(used),[d for j,d in enumerate(r[2]) if j not in used]])
print(json.dumps(dict(authority=False,diagnostic_only=True,unused_dependency_rows=unused,total_unused=sum(x[1]-x[2] for x in unused))))
